1	import { redirect } from "next/navigation";
2	import { createClient } from "@/lib/supabase/server";
3	import { MobileNav } from "@/components/shell/mobile-nav";
4	import { localDateFor } from "@/lib/outfits/local-date";
5	import { entitlementsFor } from "@/lib/billing/tiers";
6	import { closetStats, mostWorn, gatheringDust } from "@/lib/stats/aggregate";
7	import { biggestGap } from "@/lib/stats/gap";
8	import { StatsView } from "@/components/stats/stats-view";
9	import type { CandidateItem } from "@/lib/generator/candidates";
10	import type { UiOccasion } from "@/lib/generator/types";
11	
12	/** All four, so the gap answers "what should I buy", not "what suits Tuesday". */
13	const ALL_OCCASIONS: UiOccasion[] = ["everyday", "work", "weekend", "evening"];
14	
15	const TOP_N = 3;
16	
17	export default async function StatsPage() {
18	  const supabase = await createClient();
19	  const {
20	    data: { user },
21	  } = await supabase.auth.getUser();
22	  if (!user) redirect("/");
23	
24	  const [{ data: profile }, { data: itemsRaw }, { data: logs }, { data: pieces }] =
25	    await Promise.all([
26	      supabase.from("profiles").select("tier, location_timezone").eq("id", user.id).single(),
27	      supabase.from("items").select("*").eq("user_id", user.id).eq("archived", false),
28	      supabase.from("wear_logs").select("outfit_id, worn_on").eq("user_id", user.id),
29	      /**
30	       * ⚠️ `wear_logs` and `outfit_items` are NOT directly related — both hang
31	       * off `outfits`. A `wear_logs → outfit_items!inner(...)` embed returns
32	       * ZERO rows SILENTLY, which is how every item once read "0 times worn"
33	       * while SQL said otherwise (PR #22). Two explicit queries, joined below.
34	       */
35	      supabase.from("outfit_items").select("outfit_id, item_id"),
36	    ]);
37	
38	  const items = itemsRaw ?? [];
39	  const wears = logs ?? [];
40	
41	  // outfit_id → the items in it, so a wear can be attributed to each piece.
42	  const itemsByOutfit = new Map<string, string[]>();
43	  for (const p of pieces ?? []) {
44	    const list = itemsByOutfit.get(p.outfit_id) ?? [];
45	    list.push(p.item_id);
46	    itemsByOutfit.set(p.outfit_id, list);
47	  }
48	
49	  const wearsById: Record<string, number> = {};
50	  const lastWornById: Record<string, string> = {};
51	  for (const w of wears) {
52	    for (const itemId of itemsByOutfit.get(w.outfit_id) ?? []) {
53	      wearsById[itemId] = (wearsById[itemId] ?? 0) + 1;
54	      if (!lastWornById[itemId] || w.worn_on > lastWornById[itemId]) {
55	        lastWornById[itemId] = w.worn_on;
56	      }
57	    }
58	  }
59	
60	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
61	  const byId = new Map(items.map((i) => [i.id, i]));
62	  const nameOf = (id: string) => byId.get(id)?.name ?? "That piece";
63	
64	  const stats = closetStats(items, wears.flatMap((w) => (itemsByOutfit.get(w.outfit_id) ?? []).map((item_id) => ({ item_id }))));
65	  const entitlements = entitlementsFor(profile?.tier);
66	
67	  const closet: CandidateItem[] = items.map((i) => ({
68	    id: i.id,
69	    category: i.category,
70	    colors: i.colors ?? [],
71	    formality: i.formality,
72	    seasons: i.seasons ?? [],
73	    material: i.material,
74	    texture: i.texture,
75	    pattern: i.pattern,
76	  }));
77	  // Skipped entirely for a user who cannot see it — a few dozen passes over the
78	  // closet is cheap, but computing an answer nobody is shown is still waste.
79	  const gap = entitlements.gapAnalysis ? biggestGap(closet, ALL_OCCASIONS) : null;
80	
81	  return (
82	    <div className="flex min-h-dvh flex-1 flex-col">
83	      <StatsView
84	        value={stats.value}
85	        // Wears are logged against an OUTFIT, so the headline is the number of
86	        // logged outfits — not the sum of per-item attributions, which counts a
87	        // five-piece look five times.
88	        totalWears={wears.length}
89	        avgCostPerWear={stats.avgCostPerWear}
90	        mostWorn={mostWorn(items, wearsById, TOP_N).map((id) => ({
91	          id,
92	          name: nameOf(id),
93	          sub: wearsById[id] === 1 ? "Worn once" : `Worn ${wearsById[id]} times`,
94	        }))}
95	        dust={gatheringDust(items, lastWornById, today, TOP_N).map((d) => ({
96	          id: d.id,
97	          name: nameOf(d.id),
98	          days: d.days,
99	        }))}
100	        gap={
101	          gap && {
102	            label: gap.candidate.label,
103	            unlocks: gap.unlocks,
104	            reason: `It pairs with more of your closet than anything else you're missing.`,
105	          }
106	        }
107	        entitlements={{
108	          analytics: entitlements.analytics,
109	          gapAnalysis: entitlements.gapAnalysis,
110	        }}
111	        isPro={entitlements.tier === "pro"}
112	      />
113	      <MobileNav />
114	    </div>
115	  );
116	}
